package com.smarthealth.dao;
import com.smarthealth.model.Patient;import com.smarthealth.exception.DataAccessException;import java.sql.*;import java.util.*;
public class JdbcPatientDao implements GenericDao<Patient,Long>{private final ConnectionManager db;public JdbcPatientDao(ConnectionManager d){db=d;}public Optional<Patient> findById(Long id){try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM patients WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new DataAccessException("Patient lookup failed",e);}}public List<Patient> findAll(){List<Patient>x=new ArrayList<>();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM patients ORDER BY id");ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));return x;}catch(SQLException e){throw new DataAccessException("Patient query failed",e);}}public Patient save(Patient v){try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("MERGE INTO patients(id,name,age,gender,medical_history,email) KEY(id) VALUES(?,?,?,?,?,?)")){p.setLong(1,v.getId());p.setString(2,v.getName());p.setInt(3,v.getAge());p.setString(4,v.getGender());p.setString(5,v.getMedicalHistory());p.setString(6,v.getEmail());p.executeUpdate();return v;}catch(SQLException e){throw new DataAccessException("Patient save failed",e);}}public boolean delete(Long id){try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM patients WHERE id=?")){p.setLong(1,id);return p.executeUpdate()>0;}catch(SQLException e){throw new DataAccessException("Patient delete failed",e);}}private Patient map(ResultSet r)throws SQLException{return new Patient(r.getLong("id"),r.getString("name"),r.getInt("age"),r.getString("gender"),r.getString("medical_history"),r.getString("email"));}}
